// Validate incoming request from Strapi agent-chat controller
const body = $json.body || $json;
const message = (body.message || '').toString().trim();
const sessionId = (body.sessionId || 'admin-default').toString().substring(0, 128);
const user = (body.user || 'admin').toString();
const context = (body.context || 'admin-dashboard').toString();

if (!message || message.length < 1) {
  return [{ json: { _error: 'empty_message', sessionId } }];
}

// Sanitize: hard cap at 2000 chars
const safeMessage = message.substring(0, 2000);

return [{ json: {
  message: safeMessage,
  sessionId,
  user,
  context,
  timestamp: new Date().toISOString()
}}];

// Build rich context for the LLM from Strapi data
const message = $('C0 — Validate & Sanitize').item.json.message;
const sessionId = $('C0 — Validate & Sanitize').item.json.sessionId;
const user = $('C0 — Validate & Sanitize').item.json.user;

// Extract orders context
let ordersCtx = 'No recent orders data available.';
try {
  const ordersRes = $('C2 — Fetch Recent Orders').item.json;
  const orders = (ordersRes.data || []).slice(0, 10);
  if (orders.length > 0) {
    const statusCounts = {};
    let totalRevenue = 0;
    for (const o of orders) {
      const attr = o.attributes || o;
      const status = attr.status || 'unknown';
      statusCounts[status] = (statusCounts[status] || 0) + 1;
      totalRevenue += Number(attr.total_amount || 0);
    }
    ordersCtx = `Last ${orders.length} orders: ${JSON.stringify(statusCounts)}. Total revenue: ${totalRevenue} DA.`;
  }
} catch(e) {}

// Extract MCP tools list
let toolsCtx = '';
try {
  const toolsRes = $('C1 — Fetch MCP Tool Catalogue').item.json;
  const tools = (toolsRes.data?.tools || []).map(t => t.name).join(', ');
  toolsCtx = `Available data tools: ${tools}.`;
} catch(e) {}

const systemPrompt = `Tu es AXON, l'agent IA du restaurant Ralphé. Tu assistes l'administrateur avec:
- Gestion des commandes et statuts
- Analyse des performances et revenus
- Gestion du stock et alertes
- Marketing et campagnes
- Insights et recommandations business

Réponds toujours en JSON valide avec le schéma: {"reply": "...", "actions": []}
Sois concis, factuel, et proactif. Fournis des chiffres concrets quand disponibles.

Contexte temps réel:
${ordersCtx}
${toolsCtx}
Utilisateur: ${user}`;

return [{ json: {
  systemPrompt,
  userMessage: message,
  sessionId,
  ordersCtx,
  toolsCtx
}}];

