// Parse LLM response and build final reply
const sessionId = $('C3 — Build LLM Context').item.json.sessionId;
let reply = 'Directive reçue. Traitement en cours...';
let actions = [];

try {
  const raw = ($json.response || $json.text || '').toString().trim();
  // Extract JSON from the response
  const jsonMatch = raw.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    reply = (parsed.reply || parsed.message || parsed.text || raw).toString();
    actions = Array.isArray(parsed.actions) ? parsed.actions : [];
  } else if (raw) {
    reply = raw.substring(0, 1000);
  }
} catch(e) {
  // LLM returned non-JSON, use raw text
  const raw = ($json.response || '').toString();
  if (raw) reply = raw.substring(0, 800);
}

// Ensure reply is not empty
if (!reply || reply.length < 3) {
  reply = 'Je suis en cours de traitement. Reformulez votre question si nécessaire.';
}

return [{ json: {
  reply,
  actions,
  sessionId,
  model: $env.LLM_MODEL || 'llama3.1',
  provider: 'ollama'
}}];
